import java.util.Arrays;

public class Main {
    static byte[] data;
    static int pos = 0;

    static boolean skipSpace() {
        while (pos < data.length && (data[pos] & 0xff) <= ' ') pos++;
        return pos < data.length;
    }

    static String token() {
        skipSpace();
        int s = pos;
        while (pos < data.length && (data[pos] & 0xff) > ' ') pos++;
        return new String(data, s, pos - s, java.nio.charset.StandardCharsets.UTF_8);
    }

    static long num() {
        skipSpace();
        boolean neg = false;
        if (pos < data.length && (data[pos] == '-' || data[pos] == '+')) neg = data[pos++] == '-';
        long v = 0;
        while (pos < data.length && data[pos] >= '0' && data[pos] <= '9') v = v * 10 + (data[pos++] - '0');
        return neg ? -v : v;
    }

    public static void main(String[] args) throws Exception {
        data = System.in.readAllBytes();
        int n = (int) num(), m = n - 1;
        long[] u = new long[m], v = new long[m], all = new long[2 * m];
        for (int i = 0; i < m; i++) {
            u[i] = num();
            v[i] = num();
            all[2 * i] = u[i];
            all[2 * i + 1] = v[i];
        }
        Arrays.sort(all);
        int k = 0;
        for (int i = 0; i < all.length; i++)
            if (i == 0 || all[i] != all[i - 1]) all[k++] = all[i];
        long[] labels = Arrays.copyOf(all, k);
        // A path: every node has at most two neighbours.
        int[][] g = new int[k][2];
        int[] deg = new int[k];
        for (int i = 0; i < m; i++) {
            int a = Arrays.binarySearch(labels, u[i]), b = Arrays.binarySearch(labels, v[i]);
            g[a][deg[a]++] = b;
            g[b][deg[b]++] = a;
        }
        // Labels are sorted, so the first degree-1 node is the smaller endpoint.
        int cur = 0;
        while (deg[cur] != 1) cur++;
        int prev = -1;
        StringBuilder out = new StringBuilder();
        while (true) {
            if (out.length() > 0) out.append(' ');
            out.append(labels[cur]);
            int nxt = -1;
            for (int j = 0; j < deg[cur]; j++)
                if (g[cur][j] != prev) {
                    nxt = g[cur][j];
                    break;
                }
            if (nxt < 0) break;
            prev = cur;
            cur = nxt;
        }
        System.out.println(out);
    }
}

package main

import (
	"io"
	"os"
	"slices"
	"sort"
	"strconv"
)

var data []byte
var pos int

func skipSpace() bool {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	return pos < len(data)
}

func token() string {
	skipSpace()
	s := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[s:pos])
}

func num() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && (data[pos] == '-' || data[pos] == '+') {
		neg = data[pos] == '-'
		pos++
	}
	var v int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		v = v*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(num())
	m := n - 1
	u, v := make([]int64, m), make([]int64, m)
	labels := make([]int64, 0, 2*m)
	for i := 0; i < m; i++ {
		u[i], v[i] = num(), num()
		labels = append(labels, u[i], v[i])
	}
	slices.Sort(labels)
	labels = slices.Compact(labels)
	id := func(x int64) int { return sort.Search(len(labels), func(i int) bool { return labels[i] >= x }) }
	g := make([][]int, len(labels))
	for i := 0; i < m; i++ {
		a, b := id(u[i]), id(v[i])
		g[a] = append(g[a], b)
		g[b] = append(g[b], a)
	}
	// Labels are sorted, so the first degree-1 node is the smaller endpoint.
	cur := 0
	for len(g[cur]) != 1 {
		cur++
	}
	prev := -1
	out := []byte{}
	for {
		if len(out) > 0 {
			out = append(out, ' ')
		}
		out = strconv.AppendInt(out, labels[cur], 10)
		nxt := -1
		for _, x := range g[cur] {
			if x != prev {
				nxt = x
				break
			}
		}
		if nxt < 0 {
			break
		}
		prev, cur = cur, nxt
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
